#include <stdio.h>
#include <stdlib.h>

static char *inp;
static size_t ipos, ilen;

static void readAll(void) {
    size_t cap = 1u << 20;
    inp = (char *)malloc(cap);
    ilen = 0;
    for (;;) {
        if (ilen == cap) {
            cap <<= 1;
            inp = (char *)realloc(inp, cap);
        }
        size_t r = fread(inp + ilen, 1, cap - ilen, stdin);
        if (r == 0) break;
        ilen += r;
    }
}

static inline int readInt(void) {
    while (ipos < ilen && (inp[ipos] < '0' || inp[ipos] > '9')) ipos++;
    int x = 0;
    while (ipos < ilen && inp[ipos] >= '0' && inp[ipos] <= '9') {
        x = x * 10 + (inp[ipos] - '0');
        ipos++;
    }
    return x;
}

int main(void) {
    readAll();
    ipos = 0;

    int n = readInt();
    size_t p0 = ipos;

    int i, j, m, x;

    /* Como "se A nao gosta de B, B tambem nao gosta de A", montamos o grafo
       nao-direcionado (adicionando as duas direcoes), tornando o codigo
       robusto mesmo que a listagem venha apenas em um sentido. */
    int *cnt = (int *)calloc((size_t)n + 2, sizeof(int));

    for (i = 1; i <= n; i++) {
        m = readInt();
        for (j = 0; j < m; j++) {
            x = readInt();
            if (x != i) { cnt[i]++; cnt[x]++; }
        }
    }

    int *start = (int *)malloc(((size_t)n + 2) * sizeof(int));
    int *fillp = (int *)malloc(((size_t)n + 2) * sizeof(int));
    long tot = 0;
    start[0] = 0;
    for (i = 1; i <= n; i++) { start[i] = (int)tot; tot += cnt[i]; }
    start[n + 1] = (int)tot;
    for (i = 0; i <= n + 1; i++) fillp[i] = start[i];

    int *adj = (int *)malloc((size_t)(tot > 0 ? tot : 1) * sizeof(int));

    ipos = p0;
    for (i = 1; i <= n; i++) {
        m = readInt();
        for (j = 0; j < m; j++) {
            x = readInt();
            if (x != i) {
                adj[fillp[i]++] = x;
                adj[fillp[x]++] = i;
            }
        }
    }

    /* Coloracao 2-coloring por BFS comecando do aluno 1 (time 1).
       Como a solucao e unica (grafo conexo e bipartido), basta BFS. */
    int *color = (int *)malloc(((size_t)n + 1) * sizeof(int));
    int *queue = (int *)malloc(((size_t)n + 1) * sizeof(int));
    for (i = 0; i <= n; i++) color[i] = -1;

    int s;
    for (s = 1; s <= n; s++) {
        if (color[s] != -1) continue;
        int head = 0, tail = 0;
        color[s] = 0;
        queue[tail++] = s;
        while (head < tail) {
            int u = queue[head++];
            int nc = color[u] ^ 1;
            for (int e = start[u]; e < start[u + 1]; e++) {
                int v = adj[e];
                if (color[v] == -1) {
                    color[v] = nc;
                    queue[tail++] = v;
                }
            }
        }
    }

    /* Saida rapida: dois times em ordem crescente. */
    char *out = (char *)malloc(((size_t)n + 2) * 16 + 8);
    size_t op = 0;
    int t;
    for (t = 0; t <= 1; t++) {
        int first = 1;
        for (i = 1; i <= n; i++) {
            if (color[i] == t) {
                if (!first) out[op++] = ' ';
                first = 0;
                char tmp[8];
                int len = 0, v = i;
                do { tmp[len++] = (char)('0' + (v % 10)); v /= 10; } while (v);
                while (len) out[op++] = tmp[--len];
            }
        }
        out[op++] = '\n';
    }
    fwrite(out, 1, op, stdout);
    return 0;
}
